      "id": "AWS96",
      "question": "A company has 150 TB of archived image data stored on-premises that needs to be moved to the AWS Cloud within the next month. 45 The company's current network connection allows up to 100 Mbps uploads for this purpose during the night only. What is the MOST cost-effective mechanism to move this data and meet the migration deadline?",
