      "id": "AWS184",
      "question": "A company is building an application in the AWS Cloud. The application will store data in Amazon S3 buckets in two AWS Regions. The company must use an AWS Key Management Service (AWS KMS) customer managed key to encrypt all data that is stored in the S3 buckets. The data in both S3 buckets must be encrypted and decrypted with the same KMS key. The data and the key must be stored in each of the two Regions. Which solution will meet these requirements with the LEAST operational overhead?",
      "options": [
        "Create an S3 bucket in each Region. Configure the S3 buckets to use server-side encryption with Amazon S3 managed encryption keys (SSE-S3). Configure replication between the S3 buckets.",
        "Create a customer managed multi-Region KMS key. Create an S3 bucket in each Region. Configure replication between the S3 buckets. Configure the application to use the KMS key with client-side encryption.",
        "Create a customer managed KMS key and an S3 bucket in each Region. Configure the S3 buckets to use server-side encryption with Amazon S3 managed encryption keys (SSE-S3). Configure replication between the S3 buckets.",
        "Create a customer managed KMS key and an S3 bucket m each Region. Configure the S3 buckets to use server-side encryption with AWS KMS keys (SSE-KMS). Configure replication between the S3 buckets."
      ],
      "answer": 2,
      "answerLetter": "C",
      "explanation": "From \nFor most users, the default AWS KMS key store, which is protected by FIPS 140-2 validated\ncryptographic modules, fulfills their security requirements. There is no need to add an extra layer\nof maintenance responsibility or a dependency on an additional service. However, you might\nconsider creating a custom key store if your organization has any of the following requirements:\nKey material cannot be stored in a shared environment. Key material must be subject to a\nsecondary, independent audit path. The HSMs that generate and store key material must be\ncertified at FIPS 140-2 Level 3. Solusi terbaik untuk skenario ini adalah opsi (C): 'Create a customer managed KMS key and an S3 bucket in each Region. Configure the S3 buckets to use server-side encryption with Amazon S3 managed encryption keys (SSE-S3). Configure replication between the S3 buckets.'. Opsi ini mengikuti AWS Well-Architected Framework untuk keandalan, performa, dan efisiensi biaya.\n\n🔗 AWS Documentation & Solution Guide: https://docs.aws.amazon.com/kms/latest/developerguide/custom-key-store-overview.html",
      "isMultiSelect": false,
